// Checks Claude's answer and keeps only clear problems
const page = $('FromAuditPage').first().json;
const review = $json.output;
const normalize = (text) => (text || '').toLowerCase()
  .replace(/[’‘`]/g, "'").replace(/[“”]/g, '"').replace(/[–—]/g, '-').replace(/\s+/g, '');
const pageText = normalize(page.content_text);

const scores = review.scores || {};
const scoreValues = Object.values(scores);
const scoresValid = scoreValues.length === 5 && scoreValues.every(s => [0, 1, 2].includes(s));
const geoScore = scoresValid ? scoreValues.reduce((sum, s) => sum + s, 0) : null;

// Only keep an issue when Claude scored that criterion 0 (clearly missing).
// A score of 1 means "partly there": useful context, but not a backlog item.
const allIssues = review.issues || [];
const clearIssues = allIssues.filter(issue => scores[issue.criterion] === 0);

const issues = clearIssues.map(issue => ({ ...issue, evidence_found: pageText.includes(normalize(issue.evidence)) }));
const unverifiedCount = issues.filter(issue => !issue.evidence_found).length;

return { json: {
  url: page.url, page_type: page.page_type, scores, geo_score: geoScore,
  geo_issues: issues,
  issues_dropped: allIssues.length - clearIssues.length,
  unverified_count: unverifiedCount,
  needs_review: !scoresValid || unverifiedCount > 0
} };
